abstract class DataImporter {
  // the template method — final sequence, never overridden
  import(path: string) {
    const contents = this.readFile(path);
    const records = this.parse(contents);
    const valid = this.validate(records);
    this.saveToDb(valid);
  }
  protected readFile(path: string) { /* shared: read bytes from disk */ }
  protected saveToDb(records: Record[]) { /* shared: bulk insert */ }
  protected abstract parse(contents: string): Record[];
  protected abstract validate(records: Record[]): Record[];
}

class CsvImporter extends DataImporter {
  protected parse(contents: string) { /* split on commas/newlines */ }
  protected validate(records: Record[]) { /* check required CSV columns */ }
}

new CsvImporter().import('users.csv');
```

`CsvImporter` never writes `readFile()`, `saveToDb()`, or the calling sequence — it only supplies the two steps that actually differ for CSV, and `import()` guarantees they run in the right order every time.
